package com.skyclone.mod.armor;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The set catalogue ({@code data/armor/sets.json}, generated by tools/gen/armor/gen_armor.py):
 * which pieces form which set, its display name, browser category and bonus text. Pure data, no
 * Bukkit, so unit tests can load it straight from the resources folder.
 */
public final class ArmorSets {

    /** One bonus line block as written in the generator ("FULL", "TIERED", "PIECE", "ABILITY"). */
    public static final class Bonus {
        public String kind;
        public String name;
        public List<String> lines = new ArrayList<>();
    }

    /**
     * One merchant offer of a piece (wave 5), copied by the generator from the shops module's data so the
     * browser can say who sells it and what it costs: "Scrapper Nettle: Angler Helmet + 4 Rusty Coin".
     */
    public static final class Shop {
        public String piece;
        public String shop;
        /** The shops module's (renamed) NPC name, with colour codes. */
        public String npc;
        public String island;
        public String where;
        public double coins;
        /** "ITEM_ID:amount" payment items. */
        public List<String> items = new ArrayList<>();
        public String req;
    }

    /** One set (or a lone piece: {@code isSet == false}). */
    public static final class SetInfo {
        public String id;
        public String key;
        public String name;
        public String category;
        public String rarity;
        public List<String> pieces = new ArrayList<>();
        public boolean isSet;
        public List<Bonus> bonuses = new ArrayList<>();
        /** Wave 5: merchant offers of this set's pieces (empty when no shop sells them). */
        public List<Shop> shops = new ArrayList<>();
        /** Wave 5: sets whose pieces are an ingredient of this set's pieces, and the other way round. */
        public List<String> upgradeFrom = new ArrayList<>();
        public List<String> upgradeInto = new ArrayList<>();

        /** Pieces needed for the full-set bonus (3 for tuxedos and the 3-piece sets). */
        public int size() { return pieces.size(); }
    }

    /** Browser categories in display order. */
    public static final List<String> CATEGORIES = List.of(
            "COMBAT", "MINING", "FARMING", "FISHING", "FORAGING", "DUNGEONEERING", "VANILLA", "MISC");

    private final Map<String, SetInfo> byId = new LinkedHashMap<>();
    private final Map<String, String> setOfItem = new LinkedHashMap<>();

    public static ArmorSets parse(Reader reader) {
        List<SetInfo> list = new Gson().fromJson(reader, new TypeToken<List<SetInfo>>() {}.getType());
        ArmorSets s = new ArmorSets();
        if (list != null) for (SetInfo i : list) {
            if (i == null || i.id == null) continue;
            if (i.pieces == null) i.pieces = new ArrayList<>();
            if (i.bonuses == null) i.bonuses = new ArrayList<>();
            if (i.shops == null) i.shops = new ArrayList<>();
            for (Shop sh : i.shops) if (sh != null && sh.items == null) sh.items = new ArrayList<>();
            i.shops.removeIf(java.util.Objects::isNull);
            if (i.upgradeFrom == null) i.upgradeFrom = new ArrayList<>();
            if (i.upgradeInto == null) i.upgradeInto = new ArrayList<>();
            if (i.category == null || !CATEGORIES.contains(i.category)) i.category = "MISC";
            s.byId.put(i.id, i);
            for (String p : i.pieces) s.setOfItem.put(p, i.id);
        }
        return s;
    }

    public static ArmorSets load(InputStream in) {
        if (in == null) return new ArmorSets();
        try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8)) {
            return parse(r);
        } catch (Exception e) {
            throw new IllegalStateException("armor: cannot read sets.json: " + e.getMessage(), e);
        }
    }

    public SetInfo get(String setId) { return setId == null ? null : byId.get(setId); }

    public boolean has(String setId) { return byId.containsKey(setId); }

    public Collection<SetInfo> all() { return Collections.unmodifiableCollection(byId.values()); }

    /** Set id (lower snake) an item id belongs to, or null. */
    public String setOf(String itemId) { return itemId == null ? null : setOfItem.get(itemId); }

    public List<SetInfo> inCategory(String category) {
        List<SetInfo> out = new ArrayList<>();
        for (SetInfo s : byId.values()) if (s.category.equals(category)) out.add(s);
        return out;
    }

    public int pieceCount() { return setOfItem.size(); }

    /**
     * The upgrade line through a set, oldest first: walk {@code upgradeFrom} back to a set nothing feeds,
     * then {@code upgradeInto} forward to a set that feeds nothing (first link at each step; cycle-safe).
     * Angler -> Backwater; Tater -> Cropling -> Squash -> Fermenta -> Helianthus. A set with no links is
     * a line of one.
     */
    public List<String> upgradeLine(String setId) {
        List<String> out = new ArrayList<>();
        SetInfo s = get(setId);
        if (s == null) return out;
        // back from the set itself, then forward from the set itself, so the line always passes through it
        java.util.Set<String> seen = new java.util.HashSet<>();
        seen.add(s.id);
        String prev = firstKnown(s.upgradeFrom);
        while (prev != null && seen.add(prev)) {
            out.add(0, prev);
            prev = firstKnown(get(prev).upgradeFrom);
        }
        out.add(s.id);
        String next = firstKnown(s.upgradeInto);
        while (next != null && seen.add(next)) {
            out.add(next);
            next = firstKnown(get(next).upgradeInto);
        }
        return out;
    }

    private String firstKnown(List<String> ids) {
        if (ids == null) return null;
        for (String id : ids) if (byId.containsKey(id)) return id;
        return null;
    }
}
